# Generate React/Next.js Frontend for Vercel Deployment (Phase 3)
frontend_package_json = '''{
  "name": "oasis-v3-frontend",
  "version": "3.0.0",
  "description": "OASIS v3 Ultra-Lightweight AI Superintelligence Ecosystem Frontend",
  "private": true,
  "scripts": {
    "dev": "next dev",
    "build": "next build",
    "start": "next start",
    "lint": "next lint",
    "type-check": "tsc --noEmit"
  },
  "dependencies": {
    "next": "14.0.4",
    "react": "18.2.0", 
    "react-dom": "18.2.0",
    "typescript": "5.3.2",
    "@types/node": "20.10.0",
    "@types/react": "18.2.39",
    "@types/react-dom": "18.2.17",
    "tailwindcss": "3.3.6",
    "autoprefixer": "10.4.16",
    "postcss": "8.4.32",
    "@headlessui/react": "1.7.17",
    "@heroicons/react": "2.0.18",
    "framer-motion": "10.16.16",
    "axios": "1.6.2",
    "react-hot-toast": "2.4.1",
    "recharts": "2.8.0",
    "lucide-react": "0.294.0"
  },
  "devDependencies": {
    "eslint": "8.55.0",
    "eslint-config-next": "14.0.4",
    "@tailwindcss/forms": "0.5.7",
    "@tailwindcss/typography": "0.5.10"
  },
  "engines": {
    "node": ">=18.0.0"
  },
  "keywords": [
    "OASIS",
    "AI",
    "Superintelligence",
    "Mobile-First",
    "Revenue-Optimized",
    "Termux",
    "HuggingFace"
  ]
}'''

# Generate Next.js configuration
next_config = '''/** @type {import('next').NextConfig} */
const nextConfig = {
  reactStrictMode: true,
  swcMinify: true,

  // Production optimizations
  compress: true,
  poweredByHeader: false,

  // Image optimization
  images: {
    domains: ['cdn1.genspark.ai', 'images.unsplash.com', 'avatars.githubusercontent.com'],
    formats: ['image/webp', 'image/avif']
  },

  // Environment variables
  env: {
    OASIS_VERSION: '3.0.0',
    REVENUE_TARGET: '50000',
    HF_SPACES_URL: process.env.NEXT_PUBLIC_HF_SPACES_URL
  },

  // API routes optimization
  async rewrites() {
    return [
      {
        source: '/api/hf/:path*',
        destination: `${process.env.NEXT_PUBLIC_HF_SPACES_URL || 'https://elmatador0197-oasis-v3.hf.space'}/api/v3/:path*`
      }
    ]
  },

  // Performance optimizations
  experimental: {
    optimizeCss: true,
    optimizeServerReact: true
  },

  // Mobile-first optimizations
  compiler: {
    removeConsole: process.env.NODE_ENV === 'production'
  }
}

module.exports = nextConfig
'''

# Generate Vercel deployment configuration
vercel_config = '''{
  "$schema": "https://openapi.vercel.sh/vercel.json",
  "version": 2,
  "name": "oasis-v3-frontend",
  "alias": ["oasis-v3.vercel.app"],
  "description": "OASIS v3 Ultra-Lightweight AI Superintelligence Ecosystem Frontend",

  "build": {
    "env": {
      "NEXT_PUBLIC_HF_SPACES_URL": "https://elmatador0197-oasis-v3.hf.space",
      "NEXT_PUBLIC_SUPABASE_URL": "@supabase_url",
      "NEXT_PUBLIC_SUPABASE_ANON_KEY": "@supabase_anon_key",
      "NEXT_PUBLIC_APP_VERSION": "3.0.0",
      "NEXT_PUBLIC_REVENUE_TARGET": "50000",
      "NEXT_PUBLIC_ANALYTICS_ID": "@google_analytics_id"
    }
  },

  "functions": {
    "pages/api/**/*.js": {
      "runtime": "nodejs18.x",
      "maxDuration": 30
    }
  },

  "headers": [
    {
      "source": "/api/(.*)",
      "headers": [
        {
          "key": "Access-Control-Allow-Origin",
          "value": "*"
        },
        {
          "key": "Access-Control-Allow-Methods", 
          "value": "GET, POST, OPTIONS"
        },
        {
          "key": "Access-Control-Allow-Headers",
          "value": "Content-Type, Authorization"
        }
      ]
    }
  ],

  "rewrites": [
    {
      "source": "/api/hf/:match*",
      "destination": "https://elmatador0197-oasis-v3.hf.space/api/v3/:match*"
    }
  ],

  "routes": [
    {
      "src": "/robots.txt",
      "headers": {
        "Content-Type": "text/plain"
      }
    }
  ]
}'''

# Write frontend configuration files
pkg_path = "/home/user/output/oasis-v3-production/frontend/package.json"
next_path = "/home/user/output/oasis-v3-production/frontend/next.config.js"
vercel_path = "/home/user/output/oasis-v3-production/frontend/vercel.json"

with open(pkg_path, "w", encoding="utf-8") as f:
    f.write(frontend_package_json)

with open(next_path, "w", encoding="utf-8") as f:
    f.write(next_config)

with open(vercel_path, "w", encoding="utf-8") as f:
    f.write(vercel_config)

print("✅ Frontend configuration files generated")
print(f"📦 package.json: {len(frontend_package_json):,} characters")
print(f"⚙️  next.config.js: {len(next_config):,} characters")
print(f"🚀 vercel.json: {len(vercel_config):,} characters")
print("🎯 Ready for Vercel deployment with mobile-first design")
